import java.util.*;

import org.slf4j.*;

public class Main {
    private static final Logger log = LoggerFactory.getLogger(Main.class);

    // Di website ini level diatur lewat kode. Di proyek sungguhan diatur di logback.xml (materi 5).
    static void aturLevel(String nama, String level) {
        ((ch.qos.logback.classic.Logger) LoggerFactory.getLogger(nama)).setLevel(ch.qos.logback.classic.Level.toLevel(level));
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        aturLevel(Logger.ROOT_LOGGER_NAME, in.nextLine().trim());
        while (in.hasNextLine()) {
            double suhu = Double.parseDouble(in.nextLine().trim());
            log.debug("Membaca suhu {}", suhu);
            if (suhu > 39) {
                log.error("Bahaya, suhu {}", suhu);
            } else if (suhu > 37.5) {
                log.warn("Demam, suhu {}", suhu);
            } else {
                log.info("Normal, suhu {}", suhu);
            }
        }
    }
}
